(()=>{'use strict';
const menu=document.querySelector('.c1-menu'),menuToggle=document.querySelector('.c1-menu-toggle'),menuClose=document.querySelector('.c1-menu-close');let previousFocus;
function closeMenu(){menu.hidden=true;menuToggle.setAttribute('aria-expanded','false');document.body.classList.remove('c1-overlay-open');previousFocus?.focus()}
function openMenu(){previousFocus=document.activeElement;menu.hidden=false;menuToggle.setAttribute('aria-expanded','true');document.body.classList.add('c1-overlay-open');menuClose.focus()}
menuToggle.addEventListener('click',()=>menu.hidden?openMenu():closeMenu());menuClose.addEventListener('click',closeMenu);menu.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeMenu));
menu.addEventListener('keydown',e=>{if(e.key==='Escape'){closeMenu();return}if(e.key==='Tab'){const els=[...menu.querySelectorAll('button,a')];if(e.shiftKey&&document.activeElement===els[0]){e.preventDefault();els.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===els.at(-1)){e.preventDefault();els[0].focus()}}});
const reduced=matchMedia('(prefers-reduced-motion: reduce)'),motionButton=document.querySelector('.c1-motion');let motionContext,paused=false;
function configureMotion(){if(motionContext){motionContext.revert();motionContext=null}motionButton.hidden=!window.gsap||!window.ScrollTrigger||reduced.matches;motionButton.setAttribute('aria-pressed',String(paused));motionButton.textContent=paused?'Включить движение':'Остановить движение';if(reduced.matches||paused||!window.gsap||!window.ScrollTrigger)return;gsap.registerPlugin(ScrollTrigger);motionContext=gsap.context(()=>{gsap.to('.c1-portal',{scale:1.17,y:35,ease:'none',scrollTrigger:{trigger:'.c1-hero',start:'top top',end:'bottom 20%',scrub:1}});document.querySelectorAll('.c1-scene').forEach(scene=>gsap.fromTo(scene.querySelector('.c1-scene-image'),{scale:1.09},{scale:1,ease:'none',scrollTrigger:{trigger:scene,start:'top bottom',end:'bottom top',scrub:1}}))})}
motionButton.addEventListener('click',()=>{paused=!paused;configureMotion()});reduced.addEventListener('change',configureMotion);configureMotion();
document.querySelectorAll('.c1-accordion details').forEach(details=>{const summary=details.querySelector('summary');let animation;summary.addEventListener('click',e=>{if(reduced.matches||!details.animate)return;e.preventDefault();animation?.cancel();const from=details.getBoundingClientRect().height;if(details.open){animation=details.animate([{height:from+'px'},{height:summary.getBoundingClientRect().height+'px'}],{duration:340,easing:'cubic-bezier(.2,.7,.2,1)'});details.style.overflow='hidden';animation.onfinish=()=>{details.open=false;details.style.overflow='';animation=null}}else{details.open=true;const to=details.getBoundingClientRect().height;animation=details.animate([{height:from+'px'},{height:to+'px'}],{duration:380,easing:'cubic-bezier(.2,.7,.2,1)'});details.style.overflow='hidden';animation.onfinish=()=>{details.style.overflow='';animation=null}}})});
const dialog=document.querySelector('#request-dialog'),form=document.querySelector('#request-form'),result=document.querySelector('#request-result'),text=document.querySelector('#request-text'),status=document.querySelector('#request-status');let dialogFocus;
function openRequest(subject){dialogFocus=document.activeElement;if(subject){const select=form.elements.subject;if([...select.options].some(o=>o.value===subject))select.value=subject}if(!dialog.open){dialog.showModal();document.body.classList.add('c1-overlay-open')}form.elements.name.focus()}
function closeRequest(){dialog.close()}
document.querySelectorAll('.c1-request').forEach(button=>{button.hidden=false;button.addEventListener('click',()=>openRequest())});document.querySelectorAll('[data-subject]').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();openRequest(a.dataset.subject)}));dialog.querySelector('.c1-dialog-close').addEventListener('click',closeRequest);dialog.addEventListener('close',()=>{document.body.classList.remove('c1-overlay-open');dialogFocus?.focus()});dialog.addEventListener('click',e=>{if(e.target===dialog){const rect=dialog.getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)closeRequest()}});
['name','message'].forEach(key=>form.elements[key].addEventListener('input',()=>form.elements[key].setCustomValidity('')));form.addEventListener('submit',e=>{e.preventDefault();form.elements.name.setCustomValidity(form.elements.name.value.trim()?'':'Укажите ваше имя.');form.elements.message.setCustomValidity(form.elements.message.value.trim()?'':'Расскажите о вашей задаче.');if(!form.reportValidity())return;const data=new FormData(form);text.value=`Здравствуйте, DecoFlowers!\n\nМеня зовут ${data.get('name').trim()}.\nИнтересует: ${data.get('subject')}.\n\n${data.get('message').trim()}${data.get('phone').trim()?`\n\nТелефон для связи: ${data.get('phone').trim()}`:''}\n\nПодскажите, пожалуйста, доступные варианты и условия.`;form.hidden=true;result.hidden=false;status.textContent='Запрос подготовлен. Вы можете изменить текст перед передачей бренду.';text.focus()});
document.querySelector('#edit-request').addEventListener('click',()=>{result.hidden=true;form.hidden=false;form.elements.message.focus()});document.querySelector('#copy-request').addEventListener('click',async()=>{try{if(!navigator.clipboard)throw new Error();await navigator.clipboard.writeText(text.value);status.textContent='Текст скопирован. Откройте Instagram и вставьте его в сообщение.'}catch{ text.focus();text.select();status.textContent='Текст выделен. Скопируйте его сочетанием Ctrl+C или через меню устройства.'}});document.querySelector('#save-request').addEventListener('click',()=>{const url=URL.createObjectURL(new Blob([text.value],{type:'text/plain;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download='DecoFlowers-запрос.txt';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);status.textContent='Текст запроса сохранён в файл. Сообщение ещё не отправлено.'});
})();
